"""Build the local, searchable question bank. No network or paid API required."""
import json, glob, random, string
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
questions=[]
def add(text, answers, category, kind='knowledge'):
 if any(q['text']==text for q in questions):return
 if isinstance(answers,str): answers=answers.split('|')
 if answers and isinstance(answers[0],str):answers=[{'answer':a,'score':50} for a in answers]
 questions.append({'id':f'q{len(questions)+1:04d}','text':text,'answers':answers,'category':category,'kind':kind})
for f in sorted((ROOT/'data/api').rglob('reveal.json')):
 d=json.loads(f.read_text()); cat=next((x.title() for x in ['geography','sports','movies','lexicon'] if x in str(f)),'Curiosities')
 for q in d.get('rounds',d.get('prompts',[])):
  add(q['text'],[{'answer':a['answer'],'score':min(100,max(10,a.get('score',50)))} for a in q['answers']],cat,'open')
