for category,words in word_groups.items():
 for word in words.split():
  mask=''.join('_' if c in 'aeiou' else c.upper() for c in word)
  add(f'Restore the missing vowels: {mask} (hint: {category.lower()}).',word,'Wordplay','word')
 # Open prompts are scored evenly: examples are not claimed to be exhaustive.
 for letter in string.ascii_lowercase:
  candidates=[w for w in words.split() if w.startswith(letter)]
  if candidates:add(f'Name something in {category.lower()} beginning with {letter.upper()}.',candidates,category,'open')
# 600 distinct, reproducible mental-maths problems, not presented as authored trivia.
for a in range(2,22):
 for b in range(2,12):
  add(f'What is {a} × {b}?',str(a*b),'Quick maths','math')
  add(f'You have {a*b} donuts shared equally among {b} people. How many does each person get?',str(a),'Quick maths','math')
for a in range(10,30):
 for b in range(1,11):add(f'A box has {a} donuts. You give away {b}. How many remain?',str(a-b),'Quick maths','math')
(ROOT/'data/questions.json').write_text(json.dumps(questions,ensure_ascii=False,separators=(',',':')))
print(f'{len(questions)} questions, {len(set(q["category"] for q in questions))} categories')
